(()=>{
'use strict';
const KEY='makhzouni.data.v1';
const empty=()=>({products:[],sales:[],purchases:[],suppliers:[],customers:[],customerPayments:[],supplierPayments:[],expenses:[],returns:[],batches:[],closings:[],stocktakes:[],deliveries:[],audit:[],branches:[],settings:{shop:'مخزوني',currency:'MAD',pin:'',commissionRate:0}});
let db=load(),page='dashboard',searchText='',modalSave=null,activeRole=db.settings.activeRole||'owner';db.batches=db.batches||[];db.returns=db.returns||[];db.customers=db.customers||[];db.customerPayments=db.customerPayments||[];db.supplierPayments=db.supplierPayments||[];db.deliveries=db.deliveries||[];db.audit=db.audit||[];db.branches=db.branches||[];db.purchases.forEach(p=>{if(p.paid==null)p.paid=0});db.products.forEach(p=>{p.unitsPerCarton=Math.max(1,Number(p.unitsPerCarton)||1)});
let stockSnapshot=new Map((db.products||[]).map(p=>[p.id,Number(p.qty)||0]));
let savedCounts={sales:(db.sales||[]).length,purchases:(db.purchases||[]).length,returns:(db.returns||[]).length,stocktakes:(db.stocktakes||[]).length};
function load(){try{return {...empty(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return empty()}}
function audit(action,details){db.audit=db.audit||[];db.audit.push({id:id(),date:today(),created:Date.now(),role:activeRole,action,details:String(details||'')});if(db.audit.length>2000)db.audit=db.audit.slice(-2000)}
function save(){db.movements=db.movements||[];const reason=db.sales.length>savedCounts.sales?'بيع':db.purchases.length>savedCounts.purchases?'شراء':db.returns.length>savedCounts.returns?'مرتجع':db.stocktakes.length>savedCounts.stocktakes?'جرد':'تعديل مخزون';for(const p of db.products){const before=stockSnapshot.has(p.id)?stockSnapshot.get(p.id):0,after=Number(p.qty)||0,delta=after-before;if(delta!==0)db.movements.push({id:id(),date:today(),created:Date.now(),productId:p.id,productName:p.name,before,after,delta,reason:stockSnapshot.has(p.id)?reason:'رصيد أولي'});}stockSnapshot=new Map(db.products.map(p=>[p.id,Number(p.qty)||0]));audit('حفظ البيانات','تحديث بيانات النظام');savedCounts={sales:db.sales.length,purchases:db.purchases.length,returns:db.returns.length,stocktakes:db.stocktakes.length};localStorage.setItem(KEY,JSON.stringify(db));}
const $=s=>document.querySelector(s), money=n=>(Number(n)||0).toLocaleString('ar-MA',{maximumFractionDigits:2})+' د.م.';
const today=()=>{const d=new Date(),pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}, esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function sum(a,fn){return a.reduce((n,x)=>n+fn(x),0)}
function canOpenPage(p){return activeRole==='owner'||['dashboard','products','sales','debts'].includes(p)}
function setPage(p){if(!canOpenPage(p)){toast('هذه الصفحة خاصة بالمالك');return}page=p;searchText='';document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render()}
function nav(){const items=[['dashboard','▦','الرئيسية'],['products','▤','المنتجات'],['sales','↗','المبيعات'],['customers','♙','الزبائن'],['debts','د.','الديون'],['cash','د.م','الصندوق'],['reorder','↻','إعادة التزويد'],['delivery','🚚','التوصيل'],['team','♧','البائعون'],['audit','≡','سجل التعديلات'],['movements','⇄','الحركات'],['expiry','⌛','الصلاحية'],['analytics','▥','الإحصائيات'],['purchases','↙','المشتريات'],['suppliers','♙','الموردون'],['expenses','−','المصاريف'],['returns','↩','المرتجعات'],['reports','▥','التقارير'],['settings','⚙','الإعدادات']].filter(x=>canOpenPage(x[0]));$('#nav').innerHTML=items.map(x=>'<button class="nav-btn '+(page===x[0]?'active':'')+'" data-page="'+x[0]+'">'+x[1]+' <span>'+x[2]+'</span></button>').join('');$('#mobileNav').innerHTML=items.slice(0,5).map(x=>'<button class="nav-btn '+(page===x[0]?'active':'')+'" data-page="'+x[0]+'">'+x[1]+'<span>'+x[2]+'</span></button>').join('')}
function head(title,sub,action=''){return '<div class="page-head"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>'}
function stat(label,value,hint,cls=''){return '<div class="stat '+cls+'"><div class="label">'+label+'</div><div class="value">'+value+'</div><div class="hint">'+hint+'</div></div>'}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows||'<tr><td colspan="'+headers.length+'" class="empty">لا توجد بيانات بعد</td></tr>')+'</tbody></table></div>'}
function actionBtn(label,fn,cls=''){return '<button class="link-btn '+cls+'" data-action="'+fn+'">'+label+'</button>'}
function render(){nav();$('#today').textContent=new Date().toLocaleDateString('ar-MA',{weekday:'long',day:'numeric',month:'long'});const el=$('#main');const views={dashboard:dashboard,products:productsPage,sales:salesPage,customers:customersPage,debts:debtsPage,cash:cashPage,reorder:reorderPage,delivery:deliveryPage,team:teamPage,audit:auditPage,movements:movementsPage,expiry:expiryPage,analytics:analyticsPage,purchases:purchasesPage,suppliers:suppliersPage,expenses:expensesPage,returns:returnsPage,reports:reportsPage,settings:settingsPage};el.innerHTML=(views[page]||dashboard)()}
function dashboard(){
 const d=today(),ds=db.sales.filter(x=>x.date===d),de=db.expenses.filter(x=>x.date===d),revenue=sum(ds,x=>x.total),cost=sum(ds,x=>x.cost||0),exp=sum(de,x=>x.amount),low=db.products.filter(p=>p.qty<=p.min),margin=revenue?((revenue-cost)/revenue*100):0,debt=sum(db.sales,x=>Math.max(0,x.total-(x.paid||0)));
 const recent=[...db.sales].sort((a,b)=>b.created-a).slice(0,5).map(s=>'<tr><td>'+esc(s.invoice)+'</td><td>'+esc(s.date)+'</td><td>'+money(s.total)+'</td><td><span class="pill">مكتملة</span></td></tr>').join('');
 return head('الرئيسية','ملخص نشاط متجرك اليوم')+'<section class="stats">'+stat('مبيعات اليوم',money(revenue),ds.length+' فاتورة','green')+stat('صافي تقريبي اليوم',money(revenue-cost-exp),'بعد تكلفة البضاعة والمصاريف')+stat('قيمة المخزون',money(sum(db.products,p=>p.qty*p.buy)),'حسب سعر الشراء')+stat('منتجات تحتاج انتباه',low.length,'وصلت للحد الأدنى','orange')+stat('هامش الربح اليوم',margin.toFixed(1)+'%','بعد تكلفة البضاعة')+stat('ديون الزبائن',money(debt),'مبالغ غير مؤداة')+'</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h3>اختصارات سريعة</h3><span class="muted">إنجاز العمليات</span></div><div class="quick-actions"><button class="quick" data-action="add-product"><b>＋</b><span>منتج جديد</span></button><button class="quick" data-action="add-sale"><b>↗</b><span>بيع جديد</span></button><button class="quick" data-action="add-purchase"><b>↙</b><span>شراء جديد</span></button></div></section><section class="panel"><div class="panel-head"><h3>تنبيهات المخزون</h3><button class="link-btn" data-page="products">عرض المنتجات</button></div>'+(low.length?low.slice(0,5).map(p=>'<div class="panel-head"><span>'+esc(p.name)+'</span><span class="pill warn">'+p.qty+' متبقي</span></div>').join(''):'<div class="empty">كل المنتجات فوق الحد الأدنى ✓</div>')+'</section></div><section class="panel"><div class="panel-head"><h3>آخر المبيعات</h3><button class="link-btn" data-page="sales">كل المبيعات</button></div>'+table(['رقم الفاتورة','التاريخ','الإجمالي','الحالة'],recent)+'</section>'}
function searchBar(placeholder='بحث...',button='إضافة جديد',action=''){return '<div class="toolbar"><input class="search" id="searchInput" placeholder="'+placeholder+'" value="'+esc(searchText)+'"><button class="btn primary" data-action="'+action+'">＋ '+button+'</button></div>'}
function productsPage(){const arr=db.products.filter(p=>(p.name+' '+p.sku+' '+p.barcode+' '+p.category).toLowerCase().includes(searchText.toLowerCase()));const rows=arr.map(p=>'<tr><td><b>'+esc(p.name)+'</b><div class="muted">'+esc(p.category||'بدون تصنيف')+'</div></td><td>'+esc(p.sku||p.barcode||'—')+'</td><td>'+money(p.sell)+'</td><td>'+p.qty+'</td><td><span class="pill '+(p.qty<=p.min?'warn':'')+'">'+(p.qty<=p.min?'مخزون منخفض':'متوفر')+'</span></td><td><div class="actions">'+actionBtn('تعديل','edit-product:'+p.id)+actionBtn('حذف','delete-product:'+p.id,'danger-text')+'</div></td></tr>').join('');
 return head('المنتجات والمخزون','إدارة الأصناف والكميات والأسعار', '<button class="btn primary" data-action="add-product">＋ إضافة منتج</button>')+searchBar('ابحث بالاسم أو الرمز أو الباركود','إضافة منتج','add-product')+table(['المنتج','الرمز','سعر البيع','الكمية','الحالة','إجراءات'],rows)}
function salesPage(){const arr=db.sales.filter(s=>(s.invoice+' '+s.customer).toLowerCase().includes(searchText.toLowerCase())).sort((a,b)=>b.created-a.created);const rows=arr.map(s=>'<tr><td><b>'+esc(s.invoice)+'</b></td><td>'+esc(s.date)+'</td><td>'+esc(s.customer||'زبون نقدي')+'</td><td>'+money(s.total)+'</td><td>'+money(s.paid)+'</td><td>'+actionBtn('طباعة','print-sale:'+s.id)+' '+actionBtn('تفاصيل','view-sale:'+s.id)+' '+(s.total>s.paid?actionBtn('تسجيل أداء','pay-sale:'+s.id):'<span class="pill">مؤداة</span>')+'</td></tr>').join('');
 return head('المبيعات','الفواتير ومتابعة المداخيل','<button class="btn primary" data-action="add-sale">＋ تسجيل عملية بيع</button>')+searchBar('ابحث برقم الفاتورة أو الزبون','بيع جديد','add-sale')+table(['الفاتورة','التاريخ','الزبون','الإجمالي','المدفوع','إجراءات'],rows)}
function purchasesPage(){const arr=db.purchases.filter(x=>(x.supplier+' '+x.ref).toLowerCase().includes(searchText.toLowerCase())).sort((a,b)=>b.created-a.created);const rows=arr.map(x=>'<tr><td>'+esc(x.ref)+'</td><td>'+esc(x.date)+'</td><td>'+esc(x.supplier)+'</td><td>'+esc(x.productName)+'</td><td>'+x.qty+'</td><td>'+money(x.total)+'</td></tr>').join('');
 return head('المشتريات','تسجيل دخول السلع من الموردين','<button class="btn primary" data-action="add-purchase">＋ شراء جديد</button>')+searchBar('بحث بالمورد أو المرجع','شراء جديد','add-purchase')+table(['المرجع','التاريخ','المورد','المنتج','الكمية','الإجمالي'],rows)}
function suppliersPage(){const rows=db.suppliers.map(s=>'<tr><td><b>'+esc(s.name)+'</b></td><td>'+esc(s.phone||'—')+'</td><td>'+esc(s.note||'—')+'</td><td>'+actionBtn('تعديل','edit-supplier:'+s.id)+' '+actionBtn('حذف','delete-supplier:'+s.id,'danger-text')+'</td></tr>').join('');
 return head('الموردون','دفتر الموردين ومعلومات التواصل','<button class="btn primary" data-action="add-supplier">＋ مورد جديد</button>')+table(['الاسم','الهاتف','ملاحظات','إجراءات'],rows)}
function expensesPage(){const rows=db.expenses.slice().sort((a,b)=>b.created-a.created).map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.title)+'</td><td>'+esc(x.category)+'</td><td>'+money(x.amount)+'</td><td>'+actionBtn('حذف','delete-expense:'+x.id,'danger-text')+'</td></tr>').join('');
 return head('المصاريف','سجّل مصاريف المتجر لحساب الربح الصافي','<button class="btn primary" data-action="add-expense">＋ مصروف جديد</button>')+table(['التاريخ','البيان','التصنيف','المبلغ','إجراء'],rows)}
function returnsPage(){const rows=db.returns.slice().sort((a,b)=>b.created-a.created).map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.type==='sale'?'مرتجع بيع':'مرتجع شراء')+'</td><td>'+esc(x.productName)+'</td><td>'+x.qty+'</td><td>'+money(x.amount)+'</td></tr>').join('');
 return head('المرتجعات','تسجيل السلع المرجعة وضبط المخزون','<button class="btn primary" data-action="add-return">＋ تسجيل مرتجع</button>')+table(['التاريخ','النوع','المنتج','الكمية','القيمة'],rows)}
function customerBalance(name){const sales=db.sales.filter(s=>(s.customer||'زبون نقدي')===name);const sold=sum(sales,s=>Number(s.total)||0),paid=sum(sales,s=>Number(s.paid)||0);return {sales,sold,paid,due:Math.max(0,sold-paid)}}
function customersPage(){const names=[...new Set([...db.customers.map(c=>c.name),...db.sales.map(s=>s.customer).filter(Boolean)])];const rows=names.map(n=>{const c=db.customers.find(x=>x.name===n)||{},b=customerBalance(n);return '<tr><td><b>'+esc(n)+'</b></td><td>'+esc(c.phone||'—')+'</td><td>'+money(b.sold)+'</td><td>'+money(b.paid)+'</td><td>'+money(b.due)+'</td><td>'+actionBtn('كشف الحساب','customer-statement:'+encodeURIComponent(n))+' '+actionBtn('تعديل','edit-customer:'+c.id)+'</td></tr>'}).join('');return head('حسابات الزبائن','ملفات الزبائن، المشتريات، الأداءات والديون','<button class="btn primary" data-action="add-customer">＋ زبون جديد</button>')+table(['الزبون','الهاتف','إجمالي المبيعات','الأداءات','المتبقي','إجراءات'],rows)}
function customerStatement(name){const b=customerBalance(name),rows=b.sales.map(s=>'<tr><td>'+esc(s.date)+'</td><td>'+esc(s.invoice)+'</td><td>'+money(s.total)+'</td><td>'+money(s.paid)+'</td><td>'+money(Math.max(0,s.total-s.paid))+'</td><td>'+actionBtn('أداء','pay-sale:'+s.id)+'</td></tr>').join('');alert('كشف حساب: '+name+'\nإجمالي المبيعات: '+money(b.sold)+'\nالمدفوع: '+money(b.paid)+'\nالمتبقي: '+money(b.due)+'\n\n'+b.sales.map(s=>s.invoice+' | '+s.date+' | '+money(s.total)+' | باقي '+money(Math.max(0,s.total-s.paid))).join('\n'))}
function cashPage(){const d=today(),sales=db.sales.filter(s=>s.date===d),customerPays=sum(sales,s=>Number(s.paid)||0)+sum(db.customerPayments.filter(x=>x.date===d),x=>x.amount),expenses=sum(db.expenses.filter(x=>x.date===d),x=>x.amount),supplierPays=sum(db.supplierPayments.filter(x=>x.date===d),x=>x.amount),net=customerPays-expenses-supplierPays;const rows=[...sales.map(s=>'<tr><td>'+esc(s.date)+'</td><td>مبيعات محصلة</td><td>'+esc(s.invoice)+'</td><td>'+money(s.paid||0)+'</td></tr>'),...db.customerPayments.filter(x=>x.date===d).map(x=>'<tr><td>'+x.date+'</td><td>تحصيل دين</td><td>'+esc(x.customer)+'</td><td>'+money(x.amount)+'</td></tr>'),...db.expenses.filter(x=>x.date===d).map(x=>'<tr><td>'+x.date+'</td><td>مصروف</td><td>'+esc(x.title)+'</td><td>− '+money(x.amount)+'</td></tr>'),...db.supplierPayments.filter(x=>x.date===d).map(x=>'<tr><td>'+x.date+'</td><td>أداء مورد</td><td>'+esc(x.supplier)+'</td><td>− '+money(x.amount)+'</td></tr>')].join('');return head('الصندوق والتدفق النقدي','حركة المقبوضات والمدفوعات اليومية')+'<section class="stats">'+stat('المقبوضات',money(customerPays),'مبيعات وأداءات ديون','green')+stat('المصاريف',money(expenses),'مصاريف اليوم')+stat('أداءات الموردين',money(supplierPays),'مدفوعات اليوم')+stat('صافي حركة الصندوق',money(net),'قبل المطابقة النقدية')+'</section>'+table(['التاريخ','العملية','المرجع','المبلغ'],rows)}
function reorderPage(){const rows=db.products.map(p=>{const since=Date.now()-30*86400000,sold=sum(db.sales.filter(s=>s.created>=since),s=>sum((s.items||[]).filter(i=>i.productId===p.id),i=>i.qty));const daily=sold/30,target=Math.max(Number(p.min)||0,Math.ceil(daily*14)),need=Math.max(0,target-(Number(p.qty)||0));return {...p,sold,daily,target,need}}).filter(p=>p.need>0).sort((a,b)=>b.need-a.need).map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+p.qty+'</td><td>'+p.sold+'</td><td>'+p.daily.toFixed(1)+'</td><td>'+p.target+'</td><td><b>'+p.need+'</b></td></tr>').join('');return head('مساعد إعادة التزويد','اقتراح كمية تغطي 14 يوماً حسب مبيعات آخر 30 يوماً والحد الأدنى')+table(['المنتج','المخزون','المباع خلال 30 يوم','متوسط البيع اليومي','المخزون المستهدف','كمية مقترحة'],rows)}
function deliveryPage(){const rows=db.sales.map(s=>{const x=(db.deliveries||[]).find(d=>d.saleId===s.id)||{};return '<tr><td>'+esc(s.invoice)+'</td><td>'+esc(s.customer||'زبون نقدي')+'</td><td>'+esc(x.status||'جديد')+'</td><td>'+esc(x.area||'—')+'</td><td>'+esc(x.driver||'—')+'</td><td>'+actionBtn('تحديث التوصيل','delivery-update:'+s.id)+'</td></tr>'}).join('');return head('التوصيل وتتبع الطلبات','تتبع حالة كل فاتورة وتعيين المنطقة والسائق')+table(['الفاتورة','الزبون','الحالة','المنطقة','المكلف','إجراء'],rows)}
function teamPage(){const rate=Math.max(0,Number(db.settings.commissionRate)||0),rows=[...new Set(db.sales.map(s=>s.seller).filter(Boolean))].map(name=>{const sales=db.sales.filter(s=>s.seller===name),total=sum(sales,s=>s.total);return '<tr><td>'+esc(name)+'</td><td>'+sales.length+'</td><td>'+money(total)+'</td><td>'+money(total*rate/100)+'</td></tr>'}).join('');return head('البائعون والعمولات','تجميع المبيعات حسب البائع وحساب العمولة بالنسبة المحددة')+'<section class="panel">'+field('نسبة العمولة %','commissionRate','number',rate,'min="0" max="100" step="0.1"')+'<button class="btn primary" data-action="save-commission">حفظ النسبة</button></section>'+table(['البائع','عدد الفواتير','المبيعات','العمولة التقديرية'],rows)}
function auditPage(){const rows=(db.audit||[]).slice().reverse().slice(0,200).map(x=>'<tr><td>'+esc(x.date)+'</td><td>'+esc(x.role)+'</td><td>'+esc(x.action)+'</td><td>'+esc(x.details)+'</td></tr>').join('');return head('سجل التعديلات','سجل محلي لآخر العمليات والتحديثات (آخر 200 عملية)')+table(['التاريخ','الدور','العملية','التفاصيل'],rows)}
function debtsPage(){const arr=db.sales.filter(s=>Number(s.total)>Number(s.paid||0)).sort((a,b)=>b.created-a.created);const total=sum(arr,s=>Math.max(0,s.total-(s.paid||0)));const rows=arr.map(s=>'<tr><td>'+esc(s.invoice)+'</td><td>'+esc(s.customer||'زبون نقدي')+'</td><td>'+esc(s.date)+'</td><td>'+money(s.total-s.paid)+'</td><td>'+actionBtn('تسجيل أداء','pay-sale:'+s.id)+'</td></tr>').join('');return head('ديون الزبائن','الفواتير التي ما زال فيها مبلغ غير مؤدى')+stat('إجمالي الديون',money(total),arr.length+' فاتورة مفتوحة')+table(['الفاتورة','الزبون','التاريخ','المبلغ المتبقي','إجراء'],rows)}
function movementsPage(){const rows=(db.movements||[]).slice().sort((a,b)=>b.created-a.created).map(m=>'<tr><td>'+esc(m.date)+'</td><td>'+esc(m.productName)+'</td><td>'+esc(m.reason)+'</td><td>'+m.before+'</td><td>'+m.after+'</td><td><b>'+(m.delta>0?'+':'')+m.delta+'</b></td></tr>').join('');return head('سجل حركات المخزون','تتبع كل تغيير في كميات المنتجات')+table(['التاريخ','المنتج','نوع الحركة','قبل','بعد','الفرق'],rows)}
function expiryPage(){const now=new Date(),limit=new Date(now.getTime()+30*86400000);const lots=db.batches.filter(b=>Number(b.remaining)>0&&b.expiry).map(b=>({...b,expiryDate:new Date(b.expiry+'T00:00:00')})).filter(b=>b.expiryDate<=limit).sort((a,b)=>a.expiryDate-b.expiryDate);const legacy=db.products.filter(p=>p.expiry).map(p=>({...p,remaining:p.qty,expiryDate:new Date(p.expiry+'T00:00:00'),legacy:true})).filter(p=>p.expiryDate<=limit);const rows=[...lots,...legacy].map(b=>'<tr><td>'+esc(b.productName||b.name)+'</td><td>'+esc(b.expiry)+'</td><td><span class="pill '+(b.expiryDate<now?'bad':'warn')+'">'+(b.expiryDate<now?'منتهي':'قريب')+'</span></td><td>'+b.remaining+'</td><td>'+esc(b.ref||'—')+'</td></tr>').join('');return head('دفعات الصلاحية','الأقرب انتهاءً تظهر أولاً (FEFO) — تنبيه خلال 30 يوماً')+table(['المنتج','تاريخ الانتهاء','الحالة','المتبقي','مرجع الدفعة'],rows)}
function analyticsPage(){const months=[];for(let i=5;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');const sales=db.sales.filter(x=>String(x.date||'').slice(0,7)===key);const gross=sum(sales,x=>x.total),returns=sum(db.returns.filter(x=>x.type==='sale'&&String(x.date||'').slice(0,7)===key),x=>x.amount||0),cost=Math.max(0,sum(sales,x=>x.cost||0)-sum(db.returns.filter(x=>x.type==='sale'&&String(x.date||'').slice(0,7)===key),x=>x.costAmount||0)),revenue=gross-returns,expenses=sum(db.expenses.filter(x=>String(x.date||'').slice(0,7)===key),x=>x.amount);months.push({key,revenue,cost,expenses,profit:revenue-cost-expenses,margin:revenue?((revenue-cost)/revenue*100):0,count:sales.length})}const rows=months.map(m=>'<tr><td>'+m.key+'</td><td>'+money(m.revenue)+'</td><td>'+money(m.cost)+'</td><td>'+money(m.expenses)+'</td><td>'+money(m.profit)+'</td><td>'+m.margin.toFixed(1)+'%</td><td>'+m.count+'</td></tr>').join('');return head('الإحصائيات المتقدمة','مقارنة المبيعات والتكلفة والمصاريف خلال آخر 6 أشهر')+table(['الشهر','المبيعات','تكلفة البضاعة','المصاريف','الربح الصافي','هامش الربح','الفواتير'],rows)}
function reportsPage(){const fin=financeTotals(),sales=fin.netSales,cost=fin.cost,expenses=fin.expenses,purchases=sum(db.purchases,x=>x.total),debt=sum(db.sales,x=>Math.max(0,x.total-x.paid));return head('التقارير','ملخص الأداء المالي وحركة المخزون')+'<div class="report-cards"><div class="report-card"><span class="muted">إجمالي المبيعات</span><b>'+money(sales)+'</b></div><div class="report-card"><span class="muted">تكلفة البضاعة المباعة</span><b>'+money(cost)+'</b></div><div class="report-card"><span class="muted">المصاريف المسجلة</span><b>'+money(expenses)+'</b></div><div class="report-card"><span class="muted">الربح بعد المرتجعات والمصاريف</span><b>'+money(fin.profit)+'</b></div><div class="report-card"><span class="muted">مرتجعات البيع</span><b>'+money(fin.saleReturns)+'</b></div><div class="report-card"><span class="muted">المشتريات</span><b>'+money(purchases)+'</b></div><div class="report-card"><span class="muted">عدد المنتجات</span><b>'+db.products.length+'</b></div><div class="report-card"><span class="muted">ديون الزبائن (غير مدفوع)</span><b>'+money(debt)+'</b></div></div><section class="panel" style="margin-top:16px"><div class="panel-head"><h3>تصدير البيانات</h3></div><p class="muted">احتفظ بنسخة من بياناتك أو افتحها في برنامج الجداول.</p><div class="toolbar"><button class="btn primary" data-action="export-json">تنزيل نسخة احتياطية كاملة</button><button class="btn ghost" data-action="export-products">تصدير المنتجات CSV</button><button class="btn ghost" data-action="export-all-csv">تصدير شامل متوافق مع Excel</button><button class="btn ghost" data-action="export-sales">تصدير المبيعات CSV</button><button class="btn ghost" data-action="export-purchases">تصدير المشتريات CSV</button><button class="btn ghost" data-action="export-expenses">تصدير المصاريف CSV</button><button class="btn ghost" data-action="export-returns">تصدير المرتجعات CSV</button><button class="btn ghost" data-action="print-report">طباعة التقرير / PDF</button></div></section><section class="panel"><div class="panel-head"><h3>الجرد ومطابقة المخزون</h3><button class="btn ghost" data-action="stocktake">＋ جرد منتج</button></div><p class="muted">سجّل الكمية الفعلية لتصحيح فرق المخزون.</p>'+table(['التاريخ','المنتج','قبل الجرد','الكمية الفعلية','الفرق'],db.stocktakes.slice().reverse().map(x=>'<tr><td>'+x.date+'</td><td>'+esc(x.productName)+'</td><td>'+x.before+'</td><td>'+x.counted+'</td><td>'+((x.counted-x.before)>0?'+':'')+(x.counted-x.before)+'</td></tr>').join(''))+'</section><section class="panel"><div class="panel-head"><h3>إغلاق الصندوق اليومي</h3><button class="btn primary" data-action="close-day">إغلاق اليوم</button></div><p class="muted">يسجل ملخص المبيعات والمصاريف لهذا اليوم.</p>'+table(['التاريخ','المبيعات','المصاريف','عدد الفواتير'],db.closings.slice().reverse().map(c=>'<tr><td>'+c.date+'</td><td>'+money(c.sales)+'</td><td>'+money(c.expenses)+'</td><td>'+c.count+'</td></tr>').join(''))+'</section>'}
function settingsPage(){return head('الإعدادات والنسخ','إعدادات المتجر وحماية بياناتك')+'<section class="panel"><div class="panel-head"><h3>إدارة الصلاحيات</h3><span class="pill">الدور الحالي: '+(activeRole==='owner'?'المالك':'البائع')+'</span></div><p class="muted">المالك لديه جميع الصلاحيات. البائع يمكنه متابعة المنتجات وتسجيل المبيعات والدفعات فقط. رمز PIN محلي لتنظيم الأدوار فقط؛ لا يعتبر حماية قوية ضد شخص لديه وصول تقني إلى الجهاز أو بيانات المتصفح.</p><div class="form-grid">'+field('رمز دخول المالك','ownerPin','password',db.settings.ownerPin||'','minlength="4"')+field('رمز دخول البائع','sellerPin','password',db.settings.sellerPin||'','minlength="4"')+'</div><div class="toolbar"><button class="btn primary" data-action="save-roles">حفظ رموز الدخول</button><button class="btn ghost" data-action="switch-role">التبديل إلى '+(activeRole==='owner'?'البائع':'المالك')+'</button></div></section>'+'<section class="panel"><div class="panel-head"><h3>معلومات المتجر</h3></div><div class="form-grid"><div class="field"><label>اسم المتجر</label><input id="shopName" value="'+esc(db.settings.shop)+'"></div><div class="field"><label>العملة</label><input id="currency" value="الدرهم المغربي (MAD)" readonly></div></div><button class="btn primary" data-action="save-settings">حفظ الإعدادات</button></section><section class="panel"><div class="panel-head"><h3>النسخ الاحتياطي والاسترجاع</h3></div><div class="hint-box">بياناتك محفوظة محلياً في هذا المتصفح على هذا الجهاز. نزّل نسخة احتياطية بانتظام، خصوصاً قبل تغيير الهاتف أو حذف بيانات المتصفح.</div><div class="toolbar" style="margin-top:14px"><button class="btn primary" data-action="export-json">تنزيل نسخة احتياطية</button><label class="btn ghost">استرجاع نسخة<input type="file" id="importFile" accept="application/json" hidden></label></div></section><section class="panel"><div class="panel-head"><h3>أمان البيانات</h3></div><p class="muted">لا تشارك جهازك أو ملف النسخة الاحتياطية مع أشخاص غير موثوقين. حماية PIN اختيارية قيد التطوير.</p><button class="btn danger" data-action="clear-data">مسح جميع بيانات التطبيق</button></section>'}
function field(label,name,type='text',value='',extra=''){return '<div class="field"><label>'+label+'</label><input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>'}
function selectField(label,name,options){return '<div class="field"><label>'+label+'</label><select name="'+name+'">'+options.map(o=>'<option value="'+esc(o.value)+'">'+esc(o.label)+'</option>').join('')+'</select></div>'}
function openModal(title,body,fn){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;modalSave=fn;$('#modal').showModal()}
function closeModal(){$('#modal').close();modalSave=null}
function formData(){return Object.fromEntries(new FormData($('#modalForm')).entries())}
function productOptions(){return db.products.map(p=>({value:p.id,label:p.name+' — '+p.qty+' متوفر'}))}
function supplierOptions(){return db.suppliers.map(s=>({value:s.name,label:s.name}))}
function addProduct(p={}){openModal(p.id?'تعديل منتج':'إضافة منتج','<div class="form-grid">'+field('اسم المنتج','name','text',p.name||'','required')+field('رمز المنتج SKU','sku','text',p.sku||'')+field('الباركود','barcode','text',p.barcode||'')+field('التصنيف','category','text',p.category||'')+field('سعر الشراء','buy','number',p.buy??0,'min="0" step="0.01" required')+field('سعر البيع','sell','number',p.sell??0,'min="0" step="0.01" required')+field('الكمية الحالية','qty','number',p.qty??0,'min="0" step="1" required')+field('حد التنبيه (بالقطعة)','min','number',p.min??5,'min="0" step="1"')+field('عدد القطع في الكارتون','unitsPerCarton','number',p.unitsPerCarton||1,'min="1" step="1" required')+field('تاريخ انتهاء الصلاحية (اختياري)','expiry','date',p.expiry||'')+'</div>',d=>{const x={...p,...d,buy:+d.buy,sell:+d.sell,qty:+d.qty,min:+d.min,unitsPerCarton:Math.max(1,parseInt(d.unitsPerCarton,10)||1)};if(p.id)db.products=db.products.map(z=>z.id===p.id?x:z);else db.products.push({...x,id:id()});save();closeModal();render();toast('تم حفظ المنتج')})}
function addCustomer(c={}){openModal(c.id?'تعديل زبون':'إضافة زبون','<div class="form-grid">'+field('اسم الزبون','name','text',c.name||'','required')+field('الهاتف','phone','tel',c.phone||'')+field('المنطقة والعنوان','address','text',c.address||'')+field('ملاحظات','note','text',c.note||'')+'</div>',d=>{if(!d.name.trim())return toast('اسم الزبون ضروري');if(db.customers.some(x=>x.name===d.name&&x.id!==c.id))return toast('هذا الزبون مسجل مسبقاً');if(c.id)db.customers=db.customers.map(x=>x.id===c.id?{...c,...d}:x);else db.customers.push({...d,id:id(),created:Date.now()});audit('ملف زبون',d.name);save();closeModal();render();toast('تم حفظ ملف الزبون')})}
function addSupplier(s={}){openModal(s.id?'تعديل مورد':'إضافة مورد','<div class="form-grid">'+field('اسم المورد','name','text',s.name||'','required')+field('رقم الهاتف','phone','tel',s.phone||'')+'<div class="field full"><label>ملاحظات</label><input name="note" value="'+esc(s.note||'')+'"></div></div>',d=>{if(s.id)db.suppliers=db.suppliers.map(x=>x.id===s.id?{...s,...d}:x);else db.suppliers.push({...d,id:id()});save();closeModal();render();toast('تم حفظ المورد')})}
function addSale(){
 if(!db.products.length)return toast('أضف منتجاً أولاً');
 const line=()=>'<div class="cart-line form-grid" style="border:1px solid var(--line);padding:10px;border-radius:10px;margin:9px 0">'+selectField('المنتج','productId',productOptions())+field('عدد الكراتين','cartons','number',0,'min="0" step="1"')+field('القطع المفردة','qty','number',0,'min="0" step="1" required')+'<div class="field"><label>سعر البيع للوحدة</label><input name="price" type="number" min="0" step="0.01" value="'+(db.products[0]?.sell||0)+'" required></div><div class="field"><label> </label><button type="button" class="btn ghost" data-action="remove-cart-line">حذف الصنف</button></div></div>';
 openModal('فاتورة بيع جديدة','<div class="form-grid">'+field('اسم الزبون (اختياري)','customer','text','')+field('اسم البائع (اختياري)','seller','text','')+field('المبلغ المدفوع','paid','number',0,'min="0" step="0.01"')+field('تخفيض الفاتورة','discount','number',0,'min="0" step="0.01"')+field('باركود لإضافة منتج','barcodeScan','text','','inputmode="numeric" placeholder="اكتب أو امسح الباركود"')+'</div><div class="toolbar"><button type="button" class="btn ghost" data-action="scan-camera">📷 مسح بالكاميرا</button><button type="button" class="btn ghost" data-action="cart-add">＋ إضافة صنف</button></div><div id="cartLines">'+line()+'</div><div class="hint-box" id="cartTotal">المجموع: يحسب عند الحفظ. راجع الكميات والأسعار قبل تأكيد البيع.</div>',
 d=>{
  const lines=[...$('#cartLines').querySelectorAll('.cart-line')].map(el=>({productId:el.querySelector('[name="productId"]').value,qty:Number(el.querySelector('[name="qty"]').value),cartons:Number(el.querySelector('[name="cartons"]')?.value||0),price:Number(el.querySelector('[name="price"]').value)}));
  if(!lines.length)return toast('أضف صنفاً واحداً على الأقل');
  const merged={};for(const l of lines){if(!l.productId||!Number.isInteger(l.qty)||l.qty<0||!Number.isInteger(l.cartons)||l.cartons<0||!Number.isFinite(l.price)||l.price<0)return toast('تحقق من الكمية والسعر');const p=db.products.find(x=>x.id===l.productId);l.totalQty=l.qty+l.cartons*(p?.unitsPerCarton||1);if(l.totalQty<1)return toast('أدخل كارتوناً أو قطعة واحدة على الأقل');merged[l.productId]=(merged[l.productId]||0)+l.totalQty}
  for(const [pid,q] of Object.entries(merged)){const p=db.products.find(x=>x.id===pid);if(!p||q>p.qty)return toast('المخزون غير كافٍ للمنتج: '+(p?.name||''))}
  const subtotal=sum(lines,x=>x.totalQty*x.price),discount=Math.max(0,Number(d.discount)||0);if(discount>subtotal)return toast('التخفيض أكبر من مجموع الفاتورة');const items=lines.map(l=>{const p=db.products.find(x=>x.id===l.productId);const allocations=consumeBatches(p.id,l.totalQty);const lineCost=sum(allocations,x=>x.qty*x.unitCost);return {productId:p.id,productName:p.name,qty:l.totalQty,cartons:l.cartons,looseQty:l.qty,unitsPerCarton:p.unitsPerCarton,price:l.price,costUnit:l.totalQty?lineCost/l.totalQty:p.buy,lineTotal:l.totalQty*l.price,lineCost,batchAllocations:allocations}});
  
  const total=subtotal-discount,paid=Math.min(total,Math.max(0,Number(d.paid)||0)),invoice='INV-'+Date.now().toString().slice(-7);
  for(const [pid,q] of Object.entries(merged))db.products.find(x=>x.id===pid).qty-=q;
  db.sales.push({id:id(),invoice,date:today(),created:Date.now(),customer:d.customer,seller:d.seller||'',items,productName:items.map(x=>x.productName).join('، '),qty:sum(items,x=>x.qty),price:0,cost:sum(items,x=>x.lineCost),discount,total,paid,profit:total-sum(items,x=>x.lineCost)});
  save();closeModal();render();toast('تم حفظ الفاتورة '+invoice);
 });
 const first=$('#cartLines .cart-line');first.querySelector('[name="productId"]').addEventListener('change',e=>{const p=db.products.find(x=>x.id===e.target.value);first.querySelector('[name="price"]').value=p?.sell||0});
}
function addCartLine(){const box=$('#cartLines');if(!box)return;const wrap=document.createElement('div');wrap.className='cart-line form-grid';wrap.style.cssText='border:1px solid var(--line);padding:10px;border-radius:10px;margin:9px 0';wrap.innerHTML=selectField('المنتج','productId',productOptions())+field('عدد الكراتين','cartons','number',0,'min="0" step="1"')+field('القطع المفردة','qty','number',0,'min="0" step="1" required')+field('سعر البيع للقطعة','price','number',db.products[0]?.sell||0,'min="0" step="0.01" required')+'<div class="field"><label> </label><button type="button" class="btn ghost" data-action="remove-cart-line">حذف الصنف</button></div>';wrap.querySelector('[name="productId"]').addEventListener('change',e=>{const p=db.products.find(x=>x.id===e.target.value);wrap.querySelector('[name="price"]').value=p?.sell||0});box.appendChild(wrap)}
async function scanBarcode(){const input=$('#modalBody [name="barcodeScan"]');if(!input)return;if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia)return toast('المتصفح لا يدعم المسح بالكاميرا؛ استعمل خانة الباركود');let stream;try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=document.createElement('video');video.srcObject=stream;video.setAttribute('playsinline','');await video.play();const overlay=document.createElement('div');overlay.style.cssText='position:fixed;inset:0;background:#000d;z-index:99;display:grid;place-items:center;padding:20px';overlay.innerHTML='<div style="background:white;padding:12px;border-radius:12px;text-align:center"><video autoplay playsinline style="width:min(85vw,420px);border-radius:8px"></video><p>وجّه الكاميرا نحو الباركود</p><button class="btn danger" type="button">إغلاق</button></div>';const v=overlay.querySelector('video');v.srcObject=stream;document.body.appendChild(overlay);const stop=()=>{stream.getTracks().forEach(t=>t.stop());overlay.remove()};overlay.querySelector('button').onclick=stop;const tick=async()=>{if(!overlay.isConnected)return;try{const codes=await detector.detect(v);if(codes.length){input.value=codes[0].rawValue;const p=db.products.find(x=>x.barcode===input.value||x.sku===input.value);if(p){const sel=$('#cartLines .cart-line:last-child [name="productId"]');if(sel){sel.value=p.id;sel.dispatchEvent(new Event('change'))}}stop();return}}catch{}requestAnimationFrame(tick)};requestAnimationFrame(tick)}catch(e){if(stream)stream.getTracks().forEach(t=>t.stop());toast('تعذر تشغيل الكاميرا؛ تحقق من إذن الكاميرا وHTTPS')}}

function addPurchase(){if(!db.products.length)return toast('أضف منتجاً أولاً');openModal('تسجيل شراء','<div class="form-grid">'+selectField('المنتج','productId',productOptions())+selectField('المورد','supplier',supplierOptions().length?supplierOptions():[{value:'غير محدد',label:'غير محدد'}])+field('الكمية','qty','number',1,'min="1" step="1" required')+field('سعر شراء الوحدة','price','number',0,'min="0" step="0.01" required')+field('مصاريف مباشرة للشراء (اختياري)','extraCost','number',0,'min="0" step="0.01"')+field('الكمية بالكارتون (اختياري)','cartons','number',0,'min="0" step="1"')+field('تاريخ صلاحية هذه الدفعة','batchExpiry','date','')+field('مرجع الفاتورة','ref','text','')+'</div><div class="hint-box">سيتم تحديث متوسط تكلفة المخزون تلقائياً، مع توزيع المصاريف الإضافية على كمية الشراء.</div>',d=>{const p=db.products.find(x=>x.id===d.productId),cartons=Math.max(0,parseInt(d.cartons,10)||0),q=(Number(d.qty)||0)+cartons*(p?.unitsPerCarton||1),price=Number(d.price),extraCost=Math.max(0,Number(d.extraCost)||0);if(!p||!Number.isInteger(q)||q<1||!Number.isFinite(price)||price<0||!Number.isFinite(extraCost))return toast('تحقق من البيانات');const oldQty=Math.max(0,Number(p.qty)||0),oldCost=Math.max(0,Number(p.buy)||0),receivedUnitCost=(q*price+extraCost)/q,newQty=oldQty+q;p.buy=newQty?((oldQty*oldCost)+(q*price)+extraCost)/newQty:receivedUnitCost;p.qty=newQty;const purchaseTotal=q*price+extraCost;db.batches.push({id:id(),productId:p.id,productName:p.name,received:q,remaining:q,unitCost:receivedUnitCost,expiry:d.batchExpiry||'',date:today(),created:Date.now(),ref:d.ref||''});db.purchases.push({id:id(),created:Date.now(),date:today(),paid:0,productId:p.id,productName:p.name,supplier:d.supplier,qty:q,price,extraCost,unitCost:receivedUnitCost,total:purchaseTotal,ref:d.ref||'PUR-'+Date.now().toString().slice(-6)});save();closeModal();render();toast('تم تسجيل الشراء وتحديث متوسط التكلفة')})}

// Batch stock: consume the nearest-expiry lots first (FEFO); legacy/untracked stock falls back to weighted average cost.
function consumeBatches(productId,qty){
 let left=qty,used=[];
 const lots=db.batches.filter(b=>b.productId===productId&&Number(b.remaining)>0).sort((a,b)=>{
  const ax=a.expiry||'9999-12-31',bx=b.expiry||'9999-12-31';return ax.localeCompare(bx)||Number(a.created||0)-Number(b.created||0);
 });
 for(const lot of lots){if(left<=0)break;const take=Math.min(left,Number(lot.remaining)||0);if(take>0){lot.remaining-=take;used.push({batchId:lot.id,qty:take,unitCost:Number(lot.unitCost)||0,expiry:lot.expiry||''});left-=take}}
 if(left>0){const p=db.products.find(x=>x.id===productId);used.push({batchId:null,qty:left,unitCost:Number(p?.buy)||0,expiry:'',legacyStock:true})}
 return used;
}
function financeTotals(list=db.sales){
 const gross=sum(list,x=>Number(x.total)||0),saleReturns=sum(db.returns.filter(r=>r.type==='sale'),r=>Number(r.amount)||0);
 const salesCost=sum(list,x=>Number(x.cost)||0),returnedCost=sum(db.returns.filter(r=>r.type==='sale'),r=>Number(r.costAmount)||0);
 const expenses=sum(db.expenses,x=>Number(x.amount)||0);
 return {gross,netSales:gross-saleReturns,cost:Math.max(0,salesCost-returnedCost),saleReturns,expenses,profit:gross-saleReturns-Math.max(0,salesCost-returnedCost)-expenses};
}

function addExpense(){openModal('إضافة مصروف','<div class="form-grid">'+field('بيان المصروف','title','text','','required')+selectField('التصنيف','category',[{value:'كراء',label:'كراء'},{value:'أجور',label:'أجور'},{value:'نقل',label:'نقل'},{value:'كهرباء وماء',label:'كهرباء وماء'},{value:'أخرى',label:'أخرى'}])+field('المبلغ','amount','number',0,'min="0.01" step="0.01" required')+'</div>',d=>{if(+d.amount<=0)return toast('أدخل مبلغاً صحيحاً');db.expenses.push({...d,id:id(),amount:+d.amount,date:today(),created:Date.now()});save();closeModal();render();toast('تم تسجيل المصروف')})}
function addReturn(){
 if(!db.products.length)return toast('لا توجد منتجات');
 const saleOptions=db.sales.slice().reverse().map(s=>({value:s.id,label:s.invoice+' — '+(s.customer||'زبون نقدي')+' — '+s.date}));
 openModal('تسجيل مرتجع','<div class="form-grid">'+selectField('نوع المرتجع','type',[{value:'sale',label:'مرتجع بيع مرتبط بفاتورة'},{value:'purchase',label:'مرتجع شراء'}])+selectField('فاتورة البيع','saleId',[{value:'',label:'اختر الفاتورة'},...saleOptions])+selectField('المنتج','productId',productOptions())+field('الكمية','qty','number',1,'min="1" step="1" required')+field('القيمة المسترجعة','amount','number',0,'min="0" step="0.01"')+'</div><div class="hint-box">مرتجع البيع يسترجع تكلفة القطعة من الفاتورة الأصلية، وليس من سعر الشراء الحالي.</div>',d=>{
  const p=db.products.find(x=>x.id===d.productId),q=Number(d.qty),amount=Math.max(0,Number(d.amount)||0);
  if(!p||!Number.isInteger(q)||q<1)return toast('تحقق من المنتج والكمية');
  let sourceSale=null,sourceIndex=-1,unitCost=Number(p.buy)||0,costAmount=0;
  if(d.type==='sale'){
   sourceSale=db.sales.find(x=>x.id===d.saleId);
   if(!sourceSale)return toast('اختر فاتورة البيع الأصلية');
   sourceIndex=(sourceSale.items||[]).findIndex(x=>x.productId===p.id);
   if(sourceIndex<0)return toast('المنتج غير موجود في الفاتورة');
   const item=sourceSale.items[sourceIndex];
   const returned=sum(db.returns.filter(r=>r.type==='sale'&&r.saleId===sourceSale.id&&r.saleItemIndex===sourceIndex),r=>Number(r.qty)||0);
   if(q>Number(item.qty)-returned)return toast('الكمية أكبر من المتبقي القابل للإرجاع');
   unitCost=Number(item.costUnit)||(Number(item.lineCost)||0)/(Number(item.qty)||1);
   costAmount=q*unitCost;
  }else if(q>p.qty)return toast('الكمية أكبر من المخزون الحالي');
  p.qty+=d.type==='sale'?q:-q;
  if(d.type==='sale')db.batches.push({id:id(),productId:p.id,productName:p.name,received:q,remaining:q,unitCost,expiry:'',date:today(),created:Date.now(),ref:'مرتجع '+sourceSale.invoice});
  db.returns.push({id:id(),date:today(),created:Date.now(),type:d.type,productId:p.id,productName:p.name,qty:q,amount,costAmount,unitCost,saleId:sourceSale?.id||null,invoice:sourceSale?.invoice||'',saleItemIndex:sourceIndex});
  save();closeModal();render();toast('تم تسجيل المرتجع وربطه بالتكلفة الأصلية');
 });
}
function paySale(key){const s=db.sales.find(x=>x.id===key);if(!s)return;const due=Math.max(0,s.total-s.paid);openModal('تسجيل أداء فاتورة '+s.invoice,'<div class="hint-box">المبلغ المتبقي: '+money(due)+'</div>'+field('المبلغ المستلم','amount','number',due,'min="0.01" max="'+due+'" step="0.01" required'),d=>{const amount=Number(d.amount);if(!Number.isFinite(amount)||amount<=0||amount>due)return toast('المبلغ غير صحيح');s.paid=Math.min(s.total,s.paid+amount);s.payments=s.payments||[];s.payments.push({date:today(),amount,created:Date.now()});save();closeModal();render();toast('تم تسجيل الأداء')})}
function stocktake(){if(!db.products.length)return toast('أضف منتجاً أولاً');openModal('جرد المخزون','<div class="form-grid">'+selectField('المنتج','productId',productOptions())+field('الكمية الفعلية بعد العد','counted','number',0,'min="0" step="1" required')+'</div><div class="hint-box">سيتم تعديل الكمية الحالية لتطابق الكمية التي أدخلتها.</div>',d=>{const p=db.products.find(x=>x.id===d.productId),counted=Number(d.counted);if(!p||!Number.isInteger(counted)||counted<0)return toast('أدخل كمية صحيحة');const before=p.qty;p.qty=counted;db.stocktakes.push({id:id(),date:today(),productId:p.id,productName:p.name,before,counted,created:Date.now()});save();closeModal();render();toast('تم تحديث المخزون بعد الجرد')})}
function doAction(a){if(activeRole==='seller'&&!['add-sale','pay-sale','view-sale','print-sale','switch-role'].includes(a.split(':')[0]))return toast('هذه العملية خاصة بالمالك');if(a==='stocktake')return stocktake();if(a==='cart-add')return addCartLine();if(a==='scan-camera')return scanBarcode();if(a==='add-product')return addProduct();if(a==='add-sale')return addSale();if(a==='add-purchase')return addPurchase();if(a==='add-expense')return addExpense();if(a==='add-supplier')return addSupplier();if(a==='add-customer')return addCustomer();if(a==='add-return')return addReturn();const [act,key]=a.split(':');if(act==='edit-product')return addProduct(db.products.find(x=>x.id===key));if(act==='edit-supplier')return addSupplier(db.suppliers.find(x=>x.id===key));if(act==='edit-customer')return addCustomer(db.customers.find(x=>x.id===key)||{});if(act==='customer-statement')return customerStatement(decodeURIComponent(key));if(act==='delete-product'){const p=db.products.find(x=>x.id===key);if(confirm('حذف المنتج '+p.name+'؟')){db.products=db.products.filter(x=>x.id!==key);save();render()}}if(act==='delete-supplier'){if(confirm('حذف المورد؟')){db.suppliers=db.suppliers.filter(x=>x.id!==key);save();render()}}if(act==='delete-expense'){db.expenses=db.expenses.filter(x=>x.id!==key);save();render();toast('تم حذف المصروف')}if(act==='pay-sale')return paySale(key);if(act==='delivery-update'){const sale=db.sales.find(x=>x.id===key);if(!sale)return;const old=db.deliveries.find(x=>x.saleId===key)||{};openModal('تحديث التوصيل','<div class="form-grid">'+selectField('الحالة','status',['جديد','قيد التجهيز','جاهز','خرج للتوصيل','تم التسليم','تعذر التسليم','ملغي'].map(x=>({value:x,label:x})))+field('المنطقة','area','text',old.area||'')+field('السائق / البائع','driver','text',old.driver||'')+'</div>',d=>{const rec={...old,...d,saleId:key,updated:Date.now()};if(old.id)db.deliveries=db.deliveries.map(x=>x.saleId===key?rec:x);else db.deliveries.push({...rec,id:id()});audit('تحديث التوصيل',sale.invoice+' '+d.status);save();closeModal();render()})}if(act==='save-commission'){const rate=Number($('[name="commissionRate"]').value);if(!Number.isFinite(rate)||rate<0||rate>100)return toast('النسبة يجب أن تكون بين 0 و100');db.settings.commissionRate=rate;save();render();toast('تم حفظ نسبة العمولة')}if(act==='view-sale'){const s=db.sales.find(x=>x.id===key);if(s)alert('الفاتورة: '+s.invoice+'\nالمنتج: '+s.productName+'\nالكمية: '+s.qty+'\nالإجمالي: '+money(s.total)+'\nالمدفوع: '+money(s.paid))}if(act==='print-sale')return printSale(key);if(act==='export-json')return exportJSON();if(act==='export-all-csv')return csv('makhzouni-all-data.csv',['النوع','التاريخ','المرجع','الاسم','الكمية','القيمة','المدفوع','المتبقي'],[...db.products.map(p=>['منتج','',p.sku,p.name,p.qty,p.sell,'','']),...db.sales.map(x=>['بيع',x.date,x.invoice,x.customer,x.qty,x.total,x.paid,Math.max(0,x.total-x.paid)]),...db.purchases.map(x=>['شراء',x.date,x.ref,x.supplier,x.qty,x.total,'','']),...db.expenses.map(x=>['مصروف',x.date,'',x.title,'',x.amount,'','']),...(db.movements||[]).map(x=>['حركة',x.date,x.reason,x.productName,x.delta,'','',''])]);if(act==='export-products')return csv('products.csv',['المنتج','الرمز','الباركود','سعر الشراء','سعر البيع','الكمية'],db.products.map(p=>[p.name,p.sku,p.barcode,p.buy,p.sell,p.qty]));if(act==='export-sales')return csv('sales.csv',['الفاتورة','التاريخ','الزبون','المنتجات','الكمية','الإجمالي','المدفوع','الباقي'],db.sales.map(s=>[s.invoice,s.date,s.customer,s.productName,s.qty,s.total,s.paid,Math.max(0,s.total-s.paid)]));if(act==='export-purchases')return csv('purchases.csv',['المرجع','التاريخ','المورد','المنتج','الكمية','سعر الوحدة','الإجمالي'],db.purchases.map(x=>[x.ref,x.date,x.supplier,x.productName,x.qty,x.price,x.total]));if(act==='export-expenses')return csv('expenses.csv',['التاريخ','البيان','التصنيف','المبلغ'],db.expenses.map(x=>[x.date,x.title,x.category,x.amount]));if(act==='export-returns')return csv('returns.csv',['التاريخ','النوع','المنتج','الكمية','القيمة'],db.returns.map(x=>[x.date,x.type==='sale'?'مرتجع بيع':'مرتجع شراء',x.productName,x.qty,x.amount]));if(act==='print-report')return printReport();if(act==='close-day'){const d=today();if(db.closings.some(c=>c.date===d))return toast('تم إغلاق هذا اليوم مسبقاً');const ss=db.sales.filter(x=>x.date===d),ee=db.expenses.filter(x=>x.date===d);db.closings.push({date:d,sales:sum(ss,x=>x.total),expenses:sum(ee,x=>x.amount),count:ss.length});save();render();toast('تم إغلاق الصندوق اليومي')}if(act==='save-settings'){db.settings.shop=$('#shopName').value.trim()||'مخزوني';db.settings.currency='MAD';save();render();toast('تم حفظ الإعدادات')}if(act==='save-roles'){const owner=$('[name="ownerPin"]').value.trim(),seller=$('[name="sellerPin"]').value.trim();if(owner.length<4||seller.length<4)return toast('رمز كل دور يجب أن يتكون من 4 أحرف أو أرقام على الأقل');db.settings.ownerPin=owner;db.settings.sellerPin=seller;save();toast('تم حفظ رموز الدخول')}if(act==='switch-role'){const target=activeRole==='owner'?'seller':'owner',pin=prompt('أدخل رمز '+(target==='owner'?'المالك':'البائع'));if(pin===null)return;const expected=target==='owner'?db.settings.ownerPin:db.settings.sellerPin;if(!expected||pin!==expected)return toast('رمز الدخول غير صحيح أو غير مضبوط');activeRole=target;db.settings.activeRole=target;if(!canOpenPage(page))page='dashboard';save();render();toast('تم الدخول بصفة '+(target==='owner'?'المالك':'البائع'))}if(act==='clear-data'){if(prompt('اكتب مسح للتأكيد')==='مسح'){db=empty();save();render();toast('تم مسح البيانات')}}}
function download(name,content,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportJSON(){download('makhzouni-backup-'+today()+'.json',JSON.stringify(db,null,2),'application/json');toast('تم تجهيز النسخة الاحتياطية')}
function csv(name,headers,rows){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download(name,'\ufeff'+[headers,...rows].map(r=>r.map(q).join(',')).join('\n'),'text/csv;charset=utf-8')}
function printReport(){const fin=financeTotals(),sales=fin.netSales,cost=fin.cost,expenses=fin.expenses,debt=sum(db.sales,x=>Math.max(0,x.total-x.paid));const w=window.open('','_blank');if(!w)return toast('اسمح بفتح نافذة الطباعة');w.document.write('<html dir="rtl"><meta charset="utf-8"><title>تقرير '+esc(db.settings.shop)+'</title><style>body{font-family:Arial;padding:28px;color:#172b27}h1{text-align:center}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{border:1px solid #ddd;padding:9px;text-align:right}.summary{display:grid;grid-template-columns:1fr 1fr;gap:10px}.summary div{border:1px solid #ddd;padding:12px}</style><h1>'+esc(db.settings.shop)+'</h1><p>تقرير بتاريخ '+today()+'</p><div class="summary"><div>إجمالي المبيعات: '+money(sales)+'</div><div>تكلفة البضاعة: '+money(cost)+'</div><div>المصاريف: '+money(expenses)+'</div><div>الربح بعد المرتجعات: '+money(fin.profit)+'</div><div>المبالغ المتبقية: '+money(debt)+'</div><div>عدد المنتجات: '+db.products.length+'</div></div><h3>المخزون</h3><table><tr><th>المنتج</th><th>الكمية</th><th>سعر الشراء</th><th>سعر البيع</th></tr>'+db.products.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+p.qty+'</td><td>'+money(p.buy)+'</td><td>'+money(p.sell)+'</td></tr>').join('')+'</table><h3>المبيعات</h3><table><tr><th>الفاتورة</th><th>التاريخ</th><th>الزبون</th><th>الإجمالي</th><th>المدفوع</th></tr>'+db.sales.map(x=>'<tr><td>'+esc(x.invoice)+'</td><td>'+x.date+'</td><td>'+esc(x.customer||'زبون نقدي')+'</td><td>'+money(x.total)+'</td><td>'+money(x.paid)+'</td></tr>').join('')+'</table><script>window.print()<\\/script></html>');w.document.close()}
function printSale(key){const s=db.sales.find(x=>x.id===key);if(!s)return;const items=s.items||[{productName:s.productName,qty:s.qty,price:s.price,lineTotal:s.total}];const w=window.open('','_blank');if(!w)return toast('اسمح بفتح نافذة الطباعة');w.document.write('<html dir="rtl"><meta charset="utf-8"><title>فاتورة '+esc(s.invoice)+'</title><style>body{font-family:Arial;padding:35px}h1{text-align:center}table{width:100%;border-collapse:collapse;margin-top:25px}td,th{border:1px solid #ddd;padding:12px;text-align:right}.total{font-size:20px;font-weight:bold;margin-top:25px}</style><h1>'+esc(db.settings.shop)+'</h1><h3>فاتورة بيع: '+esc(s.invoice)+'</h3><p>التاريخ: '+s.date+' — الزبون: '+esc(s.customer||'زبون نقدي')+'</p><table><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr>'+items.map(i=>'<tr><td>'+esc(i.productName)+'</td><td>'+i.qty+'</td><td>'+money(i.price)+'</td><td>'+money(i.lineTotal??i.qty*i.price)+'</td></tr>').join('')+'</table><p>المجموع قبل التخفيض: '+money(sum(items,i=>i.lineTotal??i.qty*i.price))+'</p><p>التخفيض: '+money(s.discount||0)+'</p><p class="total">الإجمالي: '+money(s.total)+'</p><p>المدفوع: '+money(s.paid)+' — الباقي: '+money(Math.max(0,s.total-s.paid))+'</p><script>window.print()<\\/script></html>');w.document.close()}
document.addEventListener('click',e=>{const n=e.target.closest('[data-page]');if(n){setPage(n.dataset.page);return}const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='remove-cart-line'){const lines=$('#cartLines');if(lines?.children.length>1)a.closest('.cart-line').remove();return}doAction(a.dataset.action)}});
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){searchText=e.target.value;const pos=e.target.selectionStart;render();const x=$('#searchInput');if(x){x.focus();x.setSelectionRange(pos,pos)}}});
$('#modalForm').addEventListener('submit',e=>{e.preventDefault();if(modalSave)modalSave(formData())});$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;$('#backupBtn').onclick=exportJSON;
$('#main').addEventListener('change',e=>{if(e.target.matches('[name="barcodeScan"]')){const p=db.products.find(x=>x.barcode===e.target.value.trim()||x.sku===e.target.value.trim());if(p){let line=$('#cartLines .cart-line:last-child');if(!line){addCartLine();line=$('#cartLines .cart-line:last-child')}const sel=line.querySelector('[name="productId"]');sel.value=p.id;sel.dispatchEvent(new Event('change'));e.target.value='';toast('تم اختيار '+p.name)}else if(e.target.value.trim())toast('الباركود غير مسجل');}if(e.target.id==='importFile'&&e.target.files[0]){const f=e.target.files[0],r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.products||!x.sales)throw Error();if(confirm('سيتم استبدال البيانات الحالية. هل تريد المتابعة؟')){db={...empty(),...x};db.movements=db.movements||[];stockSnapshot=new Map((db.products||[]).map(p=>[p.id,Number(p.qty)||0]));savedCounts={sales:(db.sales||[]).length,purchases:(db.purchases||[]).length,returns:(db.returns||[]).length,stocktakes:(db.stocktakes||[]).length};save();render();toast('تم استرجاع النسخة')}}catch{toast('ملف النسخة غير صالح')}};r.readAsText(f)}});
if(!db.movements)db.movements=[];
render();
if('serviceWorker' in navigator && location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
})();